/// `wordcharCreate`.
pub fn wordchar_create() -> CharacterClass {
    let mut class = CharacterClass::with_table(&WORDCHAR_DATA, false);
    class.ranges8.push(CharacterRange::new(0x30, 0x39));
    class.ranges8.push(CharacterRange::new(0x41, 0x5a));
    class.matches8.push(0x5f);
    class.ranges8.push(CharacterRange::new(0x61, 0x7a));
    class.character_widths = CharacterClassWidths::HasBMPChars;
    class
}

/// `wordUnicodeIgnoreCaseCharCreate`.
pub fn word_unicode_ignore_case_char_create() -> CharacterClass {
    let mut class = CharacterClass::new();
    class.ranges8.push(CharacterRange::new(0x30, 0x39));
    class.ranges8.push(CharacterRange::new(0x41, 0x5a));
    class.matches8.push(0x5f);
    class.ranges8.push(CharacterRange::new(0x61, 0x7a));
    class.matches32.push(0x017f);
    class.matches32.push(0x212a);
    class.character_widths = CharacterClassWidths::HasBMPChars;
    class
}

/// `nonwordcharCreate`.
pub fn nonwordchar_create() -> CharacterClass {
    let mut class = CharacterClass::with_table(&WORDCHAR_DATA, true);
    class.ranges8.push(CharacterRange::new(0x00, 0x2f));
    class.ranges8.push(CharacterRange::new(0x3a, 0x40));
    class.ranges8.push(CharacterRange::new(0x5b, 0x5e));
    class.matches8.push(0x60);
    class.ranges8.push(CharacterRange::new(0x7b, 0xff));
    class.ranges32.push(CharacterRange::new(0x0100, 0x10ffff));
    class.character_widths = CharacterClassWidths::HasBothBMPAndNonBMP;
    class
}

/// `nonwordUnicodeIgnoreCaseCharCreate`.
pub fn nonword_unicode_ignore_case_char_create() -> CharacterClass {
    let mut class = CharacterClass::new();
    class.ranges8.push(CharacterRange::new(0x00, 0x2f));
    class.ranges8.push(CharacterRange::new(0x3a, 0x40));
    class.ranges8.push(CharacterRange::new(0x5b, 0x5e));
    class.matches8.push(0x60);
    class.ranges8.push(CharacterRange::new(0x7b, 0xff));
    class.ranges32.push(CharacterRange::new(0x0100, 0x017e));
    class.ranges32.push(CharacterRange::new(0x0180, 0x2129));
    class.ranges32.push(CharacterRange::new(0x212b, 0x10ffff));
    class.character_widths = CharacterClassWidths::HasBothBMPAndNonBMP;
    class
}

/// `newlineCreate`.
pub fn newline_create() -> CharacterClass {
    let mut class = CharacterClass::new();
    class.matches8.push(0x0a);
    class.matches8.push(0x0d);
    class.ranges32.push(CharacterRange::new(0x2028, 0x2029));
    class.character_widths = CharacterClassWidths::HasBMPChars;
    class
}

/// `spacesCreate`.
pub fn spaces_create() -> CharacterClass {
    let mut class = CharacterClass::with_table(&SPACES_DATA, false);
    class.ranges8.push(CharacterRange::new(0x09, 0x0d));
    class.matches8.push(0x20);
    class.matches8.push(0xa0);
    class.matches32.push(0x1680);
    class.ranges32.push(CharacterRange::new(0x2000, 0x200a));
    class.ranges32.push(CharacterRange::new(0x2028, 0x2029));
    class.matches32.push(0x202f);
    class.matches32.push(0x205f);
    class.matches32.push(0x3000);
    class.matches32.push(0xfeff);
    class.character_widths = CharacterClassWidths::HasBMPChars;
    class
}

