    class.ranges32.push(CharacterRange::new(0x2030, 0x205e));
    class.ranges32.push(CharacterRange::new(0x2060, 0x2fff));
    class.ranges32.push(CharacterRange::new(0x3001, 0xfefe));
    class.ranges32.push(CharacterRange::new(0xff00, 0x10ffff));
